-- Additive: new column + data update on the existing plan catalog rows only. No table dropped,
-- no tenant/subscription/salesperson/customer/visit/order data touched, no plan deleted - the
-- pricing/limits (monthlyPrice/annualPrice/maxSalespersons) that already exactly matched the
-- reference spec are left untouched; only `features` (replaced with the full structured
-- entitlement catalog - see src/lib/featureEntitlements.ts, the single source of truth these
-- values were generated from) and the new `displayOrder` column are set.

ALTER TABLE "SubscriptionPlan" ADD COLUMN "displayOrder" INTEGER NOT NULL DEFAULT 0;

UPDATE "SubscriptionPlan" SET "displayOrder" = 1 WHERE "key" = 'STARTER';
UPDATE "SubscriptionPlan" SET "displayOrder" = 2 WHERE "key" = 'GROWTH';
UPDATE "SubscriptionPlan" SET "displayOrder" = 3 WHERE "key" = 'PROFESSIONAL';
UPDATE "SubscriptionPlan" SET "displayOrder" = 4 WHERE "key" = 'BUSINESS';
UPDATE "SubscriptionPlan" SET "displayOrder" = 5 WHERE "key" = 'SCALE';
UPDATE "SubscriptionPlan" SET "displayOrder" = 6 WHERE "key" = 'ENTERPRISE';
UPDATE "SubscriptionPlan" SET "displayOrder" = 100 WHERE "key" = 'LEGACY';

